function normalizeFa(text) {
  if (text === undefined || text === null) return '';
  let s = String(text);
  s = s.replace(/ي/g, 'ی').replace(/ك/g, 'ک');
  s = s.replace(/[‌‏‎]/g, ' ');
  const faDigits = '۰۱۲۳۴۵۶۷۸۹';
  const arDigits = '٠١٢٣٤٥٦٧٨٩';
  s = s.replace(/[۰-۹]/g, function (d) { return String(faDigits.indexOf(d)); });
  s = s.replace(/[٠-٩]/g, function (d) { return String(arDigits.indexOf(d)); });
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

const item = $input.first().json;
const channel = item.channel;
const channelUserId = String(item.channelUserId || '');
const rawInput = item.input || {};
const inputType = rawInput.type === 'choice' ? 'choice' : 'text';
const rawValue = rawInput.value !== undefined ? rawInput.value : '';
const normalizedValue = inputType === 'text' ? normalizeFa(rawValue) : String(rawValue);

if (!channel || !['telegram', 'web'].includes(channel) || !channelUserId) {
  throw new Error('ورودی نامعتبر: channel یا channelUserId ناقص است');
}

return [{
  json: {
    channel: channel,
    channelUserId: channelUserId,
    input: { type: inputType, value: normalizedValue, rawValue: rawValue }
  }
}];

const normInput = $('نرمال‌سازی و اعتبارسنجی ورودی').first().json;
const convItem = $('خواندن مکالمه').first();
const convRow = convItem ? convItem.json : null;
const state = (convRow && convRow.state) || { step: 'main_menu' };
const pa = state.parentAuth || {};
const locked = pa.lockedUntil && new Date(pa.lockedUntil).getTime() > Date.now();
const needsLookup = state.step === 'parent_auth' && normInput.input.type === 'text' && !locked;
return [{ json: { needsLookup: needsLookup } }];

function normalizeFa(text) {
  if (text === undefined || text === null) return '';
  let s = String(text);
  s = s.replace(/ي/g, 'ی').replace(/ك/g, 'ک');
  s = s.replace(/[‌‏‎]/g, ' ');
  const faDigits = '۰۱۲۳۴۵۶۷۸۹';
  const arDigits = '٠١٢٣٤٥٦٧٨٩';
  s = s.replace(/[۰-۹]/g, function (d) { return String(faDigits.indexOf(d)); });
  s = s.replace(/[٠-٩]/g, function (d) { return String(arDigits.indexOf(d)); });
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

function genRef() {
  const n = Math.floor(100000 + Math.random() * 900000);
  return 'TCK-' + n;
}

// TODO: اگر مدیر می‌خواهد فهرست پایه‌ها را ویرایش کند، باید ستون ساختاریافته‌ای
// برای پایه‌ها به schema اضافه شود؛ فعلاً چون در faq/settings مقدار ساختاریافته‌ای
// برای پایه‌ها نیست، این فهرست ثابت (نه محتوای متنی مدرسه، بلکه گزینه‌های فرم) است.
const GRADE_OPTIONS = ['پیش‌دبستان', 'اول', 'دوم', 'سوم', 'چهارم', 'پنجم', 'ششم'];
const PARENT_CATEGORIES = ['مالی', 'آموزشی', 'انضباطی', 'مرخصی', 'سایر'];
const LOCK_MS = 60 * 60 * 1000;

const normInput = $('نرمال‌سازی و اعتبارسنجی ورودی').first().json;
const channel = normInput.channel;
const channelUserId = normInput.channelUserId;
const input = normInput.input;

const convRows = $('خواندن مکالمه').all();
const settingsRows = $('خواندن تنظیمات').all();
const faqRowsRaw = $('خواندن FAQ').all();

const readError = (convRows[0] && convRows[0].json && convRows[0].json.error) ||
  (settingsRows[0] && settingsRows[0].json && settingsRows[0].json.error) ||
  (faqRowsRaw[0] && faqRowsRaw[0].json && faqRowsRaw[0].json.error);

const settings = {};
if (!(settingsRows[0] && settingsRows[0].json && settingsRows[0].json.error)) {
  for (const r of settingsRows) { if (r.json && r.json.key) settings[r.json.key] = r.json.value; }
}
const officePhone = settings.office_phone || 'دفتر مدرسه';
const settingsMeta = { schoolName: settings.school_name || '', officePhone: officePhone };

if (readError) {
  return [{ json: {
    channel: channel, channelUserId: channelUserId,
    reply: {
      messages: ['در حال حاضر امکان پردازش درخواست شما نیست. لطفاً کمی بعد دوباره تلاش کنید یا با دفتر مدرسه تماس بگیرید: ' + officePhone],
      choices: [], expectsInput: null
    },
    newState: null, action: 'skip_save', actionPayload: {}, settingsMeta: settingsMeta
  } }];
}

const faqRows = faqRowsRaw.filter(function (r) { return !r.json.error; }).map(function (r) { return r.json; });
const threshold = parseInt(settings.faq_match_threshold, 10) || 1;

let state = {};
if (convRows.length && convRows[0].json && convRows[0].json.state) {
  state = convRows[0].json.state;
}
if (!state || !state.step) state = { step: 'main_menu' };

function buildMainMenuChoices() {
  const menuFaq = faqRows
    .filter(function (f) { return f.menu_path && f.menu_path.trim() !== ''; })
    .sort(function (a, b) { return a.sort_order - b.sort_order; })
    .map(function (f) { return { id: 'faq:' + f.id, label: f.menu_path }; });
  return menuFaq.concat([
    { id: 'ask_more', label: 'سؤال دیگری دارم' },
    { id: 'parent_login', label: 'ورود اولیا (با کد رهگیری)' }
  ]);
}

function matchFaq(text) {
  const norm = normalizeFa(text);
  let best = null, bestScore = 0;
  for (const f of faqRows) {
    let score = 0;
    for (const kw of (f.keywords || [])) {
      if (norm.includes(normalizeFa(kw))) score++;
    }
    if (score > bestScore) { bestScore = score; best = f; }
  }
  return { best: best, score: bestScore };
}

let reply = { messages: [], choices: [], expectsInput: null };
let action = 'none';
let actionPayload = {};
let newState = state;

const step = state.step;

if (step === 'main_menu') {
  if (input.type === 'choice' && input.value === 'show_menu') {
    reply.messages = [settings.motto || ('به سامانه‌ی پاسخگویی ' + (settings.school_name || 'دبستان هدف') + ' خوش آمدید.')];
    reply.choices = buildMainMenuChoices();
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };

  } else if (input.type === 'choice' && input.value === 'ask_more') {
    reply.messages = ['سؤال خود را بنویسید.'];
    reply.choices = [];
    reply.expectsInput = { type: 'text', field: 'main_menu.free_text' };
    newState = { step: 'main_menu' };

  } else if (input.type === 'choice' && input.value === 'parent_login') {
    reply.messages = ['کد رهگیری اختصاصی فرزندتان را وارد کنید.'];
    reply.choices = [];
    reply.expectsInput = { type: 'text', field: 'parent_auth.code' };
    newState = { step: 'parent_auth', parentAuth: { attempts: 0, lockedUntil: null, studentId: null } };

  } else if (input.type === 'choice' && input.value === 'start_registration') {
    reply.messages = ['پایه‌ی تحصیلی فرزندتان را انتخاب کنید.'];
    reply.choices = GRADE_OPTIONS.map(function (g) { return { id: 'grade:' + g, label: g }; });
    reply.expectsInput = { type: 'choice', field: 'registration.grade' };
    newState = { step: 'registration', registration: { stage: 'grade', data: {} } };

  } else if (input.type === 'choice' && input.value.indexOf('faq:') === 0) {
    const id = parseInt(input.value.split(':')[1], 10);
    const faq = faqRows.find(function (f) { return f.id === id; });
    if (faq) {
      reply.messages = [faq.answer];
      reply.choices = faq.menu_path === 'ثبت‌نام'
        ? [{ id: 'start_registration', label: 'شروع ثبت‌نام' }, { id: 'show_menu', label: 'بازگشت به منو' }]
        : [{ id: 'show_menu', label: 'بازگشت به منو' }];
    } else {
      reply.messages = ['موردی یافت نشد.'];
      reply.choices = [{ id: 'show_menu', label: 'بازگشت به منو' }];
    }
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };

  } else if (input.type === 'text' && input.value) {
    const m = matchFaq(input.value);
    if (m.best && m.score >= threshold) {
      reply.messages = [m.best.answer];
      reply.choices = [{ id: 'show_menu', label: 'بازگشت به منو' }];
      reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    } else {
      const ref = genRef();
      reply.messages = ['پاسخ آماده‌ای برای این سؤال نداریم. درخواست شما با کد پیگیری ' + ref + ' ثبت شد و همکاران ما پاسخ خواهند داد.'];
      reply.choices = [{ id: 'show_menu', label: 'بازگشت به منو' }];
      reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
      action = 'insert_ticket_free';
      actionPayload = { channel: channel, channelUserId: channelUserId, body: (input.rawValue !== undefined ? input.rawValue : input.value), publicRef: ref };
    }
    newState = { step: 'main_menu' };

  } else {
    reply.messages = ['متوجه نشدم. یکی از گزینه‌ها را انتخاب کنید یا سؤالتان را بنویسید.'];
    reply.choices = buildMainMenuChoices();
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };
  }

} else if (step === 'registration') {
  const reg = state.registration || { stage: 'grade', data: {} };

  if (input.type === 'choice' && input.value === 'show_menu') {
    reply.messages = ['به منوی اصلی بازگشتید.'];
    reply.choices = buildMainMenuChoices();
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };

  } else if (reg.stage === 'grade') {
    if (input.type === 'choice' && input.value.indexOf('grade:') === 0) {
      reg.data.grade = input.value.split(':')[1];
      reg.stage = 'student_name';
      reply.messages = ['نام و نام خانوادگی دانش‌آموز را بنویسید.'];
      reply.expectsInput = { type: 'text', field: 'registration.student_name' };
    } else {
      reply.messages = ['لطفاً یکی از پایه‌های زیر را انتخاب کنید.'];
      reply.choices = GRADE_OPTIONS.map(function (g) { return { id: 'grade:' + g, label: g }; });
      reply.expectsInput = { type: 'choice', field: 'registration.grade' };
    }
    newState = { step: 'registration', registration: reg };

  } else if (reg.stage === 'student_name') {
    if (input.type === 'text' && input.value) {
      reg.data.student_name = input.value;
      reg.stage = 'parent_name';
      reply.messages = ['نام و نام خانوادگی ولی را بنویسید.'];
      reply.expectsInput = { type: 'text', field: 'registration.parent_name' };
    } else {
      reply.messages = ['نام دانش‌آموز را بنویسید.'];
      reply.expectsInput = { type: 'text', field: 'registration.student_name' };
    }
    newState = { step: 'registration', registration: reg };

  } else if (reg.stage === 'parent_name') {
    if (input.type === 'text' && input.value) {
      reg.data.parent_name = input.value;
      reg.stage = 'phone';
      reply.messages = ['شماره موبایل خود را وارد کنید (مثال: 09123456789).'];
      reply.expectsInput = { type: 'text', field: 'registration.phone' };
    } else {
      reply.messages = ['نام ولی را بنویسید.'];
      reply.expectsInput = { type: 'text', field: 'registration.parent_name' };
    }
    newState = { step: 'registration', registration: reg };

  } else if (reg.stage === 'phone') {
    const digits = normalizeFa(input.value || '');
    if (input.type === 'text' && /^09\d{9}$/.test(digits)) {
      reg.data.phone = digits;
      reg.stage = 'note';
      reply.messages = ['اگر توضیح خاصی دارید بنویسید، یا رد شوید.'];
      reply.choices = [{ id: 'skip_note', label: 'ندارم' }];
      reply.expectsInput = { type: 'text', field: 'registration.note' };
    } else {
      reply.messages = ['شماره موبایل نامعتبر است. شماره را به شکل 09xxxxxxxxx وارد کنید.'];
      reply.expectsInput = { type: 'text', field: 'registration.phone' };
    }
    newState = { step: 'registration', registration: reg };

  } else if (reg.stage === 'note') {
    if (input.type === 'choice' && input.value === 'skip_note') {
      reg.data.note = null;
    } else if (input.type === 'text') {
      reg.data.note = input.value || null;
    }
    reg.stage = 'summary';
    reply.messages = [
      'خلاصه‌ی ثبت‌نام:',
      'پایه: ' + reg.data.grade,
      'نام دانش‌آموز: ' + reg.data.student_name,
      'نام ولی: ' + reg.data.parent_name,
      'موبایل: ' + reg.data.phone,
      'توضیح: ' + (reg.data.note || '—')
    ];
    reply.choices = [{ id: 'confirm_registration', label: 'تأیید و ثبت' }, { id: 'edit_registration', label: 'ویرایش از نو' }];
    reply.expectsInput = { type: 'choice', field: 'registration.confirm' };
    newState = { step: 'registration', registration: reg };

  } else if (reg.stage === 'summary') {
    if (input.type === 'choice' && input.value === 'confirm_registration') {
      reply.messages = ['ثبت‌نام شما با موفقیت ثبت شد. دفتر مدرسه به‌زودی با شما تماس می‌گیرد.'];
      reply.choices = [{ id: 'show_menu', label: 'بازگشت به منو' }];
      reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
      action = 'insert_lead';
      actionPayload = Object.assign({}, reg.data, { channel: channel });
      newState = { step: 'main_menu' };
    } else if (input.type === 'choice' && input.value === 'edit_registration') {
      reply.messages = ['پایه‌ی تحصیلی فرزندتان را دوباره انتخاب کنید.'];
      reply.choices = GRADE_OPTIONS.map(function (g) { return { id: 'grade:' + g, label: g }; });
      reply.expectsInput = { type: 'choice', field: 'registration.grade' };
      newState = { step: 'registration', registration: { stage: 'grade', data: {} } };
    } else {
      reply.messages = ['لطفاً تأیید یا ویرایش را انتخاب کنید.'];
      reply.choices = [{ id: 'confirm_registration', label: 'تأیید و ثبت' }, { id: 'edit_registration', label: 'ویرایش از نو' }];
      reply.expectsInput = { type: 'choice', field: 'registration.confirm' };
      newState = { step: 'registration', registration: reg };
    }
  }

} else if (step === 'parent_auth') {
  const pa = state.parentAuth || { attempts: 0, lockedUntil: null, studentId: null };

  if (input.type === 'choice' && input.value === 'show_menu') {
    reply.messages = ['به منوی اصلی بازگشتید.'];
    reply.choices = buildMainMenuChoices();
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };

  } else if (pa.lockedUntil && new Date(pa.lockedUntil).getTime() > Date.now()) {
    reply.messages = ['به دلیل ورود اشتباه مکرر، امکان تلاش مجدد وجود ندارد. لطفاً بعداً تلاش کنید یا با دفتر تماس بگیرید: ' + officePhone];
    reply.choices = [{ id: 'show_menu', label: 'بازگشت به منو' }];
    reply.expectsInput = { type: 'text', field: 'parent_auth.code' };
    newState = { step: 'parent_auth', parentAuth: pa };

  } else {
    let student = null;
    try {
      const rows = $('جستجوی دانش‌آموز با کد').all();
      if (rows.length && !rows[0].json.error && rows[0].json.id) student = rows[0].json;
    } catch (e) { student = null; }

    if (student) {
      reply.messages = ['خوش آمدید. دسته‌ی مورد نظر برای ثبت درخواست را انتخاب کنید.'];
      reply.choices = PARENT_CATEGORIES.map(function (c) { return { id: 'cat:' + c, label: c }; }).concat([{ id: 'show_menu', label: 'بازگشت به منوی اصلی' }]);
      reply.expectsInput = { type: 'choice', field: 'parent_menu.category' };
      action = 'verify_parent_success';
      actionPayload = { channel: channel, channelUserId: channelUserId, studentId: student.id };
      newState = { step: 'parent_menu', parentAuth: { attempts: 0, lockedUntil: null, studentId: student.id } };
    } else {
      const attempts = (pa.attempts || 0) + 1;
      if (attempts >= 3) {
        newState = { step: 'parent_auth', parentAuth: { attempts: 0, lockedUntil: new Date(Date.now() + LOCK_MS).toISOString(), studentId: null } };
        reply.messages = ['کد وارد شده صحیح نیست. به دلیل سه بار ورود نادرست، تا یک ساعت دیگر امکان تلاش مجدد نیست.'];
      } else {
        newState = { step: 'parent_auth', parentAuth: { attempts: attempts, lockedUntil: null, studentId: null } };
        reply.messages = ['کد وارد شده صحیح نیست. دوباره تلاش کنید.'];
      }
      reply.choices = [{ id: 'show_menu', label: 'بازگشت به منو' }];
      reply.expectsInput = { type: 'text', field: 'parent_auth.code' };
    }
  }

} else if (step === 'parent_menu') {
  if (input.type === 'choice' && input.value === 'show_menu') {
    reply.messages = ['به منوی اصلی بازگشتید.'];
    reply.choices = buildMainMenuChoices();
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };
  } else if (input.type === 'choice' && input.value.indexOf('cat:') === 0) {
    const category = input.value.split(':')[1];
    reply.messages = ['متن درخواست خود را بنویسید.'];
    reply.expectsInput = { type: 'text', field: 'parent_ticket.body' };
    newState = { step: 'parent_ticket', parentAuth: state.parentAuth, parentTicket: { category: category } };
  } else {
    reply.messages = ['دسته‌ی مورد نظر را انتخاب کنید.'];
    reply.choices = PARENT_CATEGORIES.map(function (c) { return { id: 'cat:' + c, label: c }; }).concat([{ id: 'show_menu', label: 'بازگشت به منوی اصلی' }]);
    reply.expectsInput = { type: 'choice', field: 'parent_menu.category' };
    newState = { step: 'parent_menu', parentAuth: state.parentAuth };
  }

} else if (step === 'parent_ticket') {
  if (input.type === 'choice' && input.value === 'show_menu') {
    reply.messages = ['به منوی اصلی بازگشتید.'];
    reply.choices = buildMainMenuChoices();
    reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
    newState = { step: 'main_menu' };
  } else if (input.type === 'text' && input.value) {
    const ref = genRef();
    action = 'insert_ticket_parent';
    actionPayload = {
      channel: channel, channelUserId: channelUserId,
      studentId: (state.parentAuth && state.parentAuth.studentId) || null,
      category: (state.parentTicket && state.parentTicket.category) || 'سایر',
      body: (input.rawValue !== undefined ? input.rawValue : input.value),
      publicRef: ref
    };
    reply.messages = ['درخواست شما ثبت شد. کد پیگیری: ' + ref];
    reply.choices = PARENT_CATEGORIES.map(function (c) { return { id: 'cat:' + c, label: c }; }).concat([{ id: 'show_menu', label: 'بازگشت به منوی اصلی' }]);
    reply.expectsInput = { type: 'choice', field: 'parent_menu.category' };
    newState = { step: 'parent_menu', parentAuth: state.parentAuth };
  } else {
    reply.messages = ['متن درخواست را بنویسید.'];
    reply.expectsInput = { type: 'text', field: 'parent_ticket.body' };
    newState = { step: 'parent_ticket', parentAuth: state.parentAuth, parentTicket: state.parentTicket };
  }

} else {
  reply.messages = ['به منوی اصلی بازگشتید.'];
  reply.choices = buildMainMenuChoices();
  reply.expectsInput = { type: 'choice', field: 'main_menu.choice' };
  newState = { step: 'main_menu' };
}

return [{ json: {
  channel: channel, channelUserId: channelUserId,
  reply: reply, newState: newState, action: action, actionPayload: actionPayload,
  settingsMeta: settingsMeta
} }];

const decision = $('موتور تصمیم‌گیری نهایی').first().json;

let convError = null;
try {
  const convRes = $('ذخیره وضعیت مکالمه').first().json;
  if (convRes && convRes.error) convError = convRes.error;
} catch (e) { /* اگر شاخه‌ی skip_save بوده، این نود اصلاً اجرا نشده است */ }

if (convError) {
  return [{ json: {
    messages: ['خطایی در ذخیره‌سازی اطلاعات رخ داد. لطفاً دوباره تلاش کنید یا با دفتر تماس بگیرید: ' + (decision.settingsMeta ? decision.settingsMeta.officePhone : '')],
    choices: [], expectsInput: null,
    meta: decision.settingsMeta
  } }];
}

return [{ json: Object.assign({}, decision.reply, { meta: decision.settingsMeta }) }];
